<?php require __DIR__.'/../bootstrap/app.php';$items=Database::get()->query("SELECT s.*,c.name category FROM services s LEFT JOIN service_categories c ON c.id=s.category_id WHERE s.is_active=1")->fetchAll();$title='Technical services';require __DIR__.'/../app/Views/header.php';?><section class="pagehead"><div class="container"><h1>Technical services</h1><p>Browse and request a service.</p></div></section><section class="section"><div class="container row g-3"><?php foreach($items as $s):?><div class="col-md-4"><div class="cardx"><div class="eyebrow"><?=e($s['category']??'Service')?></div><h3><?=e($s['name'])?></h3><p><?=e($s['description'])?></p><p><?=$s['base_price']===null?'Request a quote':number_format((float)$s['base_price'],2).' ETB'?></p><a class="btn gold" href="<?=e(url('request_service.php?id='.(int)$s['id']))?>">Request service</a></div></div><?php endforeach;?><?php if(!$items):?><p>No active services yet.</p><?php endif;?></div></section><?php require __DIR__.'/../app/Views/footer.php';?>